import{_ as r,o as t,c as o,a2 as a}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Version 1.0.0.36 Launched","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.36-launched.md","filePath":"change-log/release/version-1.0.0.36-launched.md"}'),n={name:"change-log/release/version-1.0.0.36-launched.md"};function s(i,e,l,d,c,g){return t(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="version-1-0-0-36-launched" tabindex="-1">Version 1.0.0.36 Launched <a class="header-anchor" href="#version-1-0-0-36-launched" aria-label="Permalink to &quot;Version 1.0.0.36 Launched&quot;">​</a></h1><p><strong>31st October 2025</strong></p><hr><h3 id="theme-performance-enhancements" tabindex="-1"><strong>Theme &amp; Performance Enhancements</strong> <a class="header-anchor" href="#theme-performance-enhancements" aria-label="Permalink to &quot;**Theme &amp; Performance Enhancements**&quot;">​</a></h3><ol><li><strong>🚀 75% Faster Startup</strong><ul><li>Tradeboard now launches <strong>in ~2 seconds</strong> (previously 5–8 seconds).</li><li>Achieved by <strong>parallelizing all 11 database connections</strong> and <strong>concurrent service startups</strong> (execution engine, scheduler, WebSocket manager).</li><li>Delivers an instant, ready-to-trade experience every time you restart the server.</li></ul></li><li><strong>⚡ Platform Speed &amp; Latency Optimizations</strong><ul><li>Introduced <strong>Order Latency Dashboard v2</strong> with detailed latency segmentation: <ul><li>Platform Overhead</li><li>Broker API Time</li><li>Network RTT</li></ul></li><li>Added <strong>broker-level latency tracking</strong> to the HTTPX client.</li><li>Improved in-memory caching for <strong>API keys and symbol data</strong> for quicker responses.</li><li>Average platform response time reduced by <strong>40–60%</strong>.</li></ul></li><li><strong>🎨 UI &amp; Frontend Updates</strong><ul><li><code>socket.io</code> now served from <strong>local file</strong> (no external CDN dependency).</li><li>Smart audio filtering — notifications now play <strong>only for order placement</strong>.</li><li>Fixed theme contrast issues, form alignments, and modal responsiveness across brokers.</li></ul></li></ol><hr><h3 id="new-api-launches" tabindex="-1"><strong>New API Launches</strong> <a class="header-anchor" href="#new-api-launches" aria-label="Permalink to &quot;**New API Launches**&quot;">​</a></h3><p>Introducing <strong>4 Important Tradeboard APIs</strong> — available in both <strong>REST API</strong> and <strong>Python SDK</strong>:</p><ol><li><strong>OptionsOrder</strong><br> 📘 <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/orders-api/optionsorder" target="_blank" rel="noreferrer">Docs</a><br> Place and modify options orders programmatically with advanced parameter support.</li><li><strong>OptionSymbol</strong><br> 📘 <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/data-api/optionsymbol" target="_blank" rel="noreferrer">Docs</a><br> Retrieve complete option chain details — strikes, expiries, and instrument tokens.</li><li><strong>OptionGreeks</strong><br> 📘 <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/data-api/optiongreeks" target="_blank" rel="noreferrer">Docs</a><br> Get live Greeks (Delta, Gamma, Vega, Theta, IV) calculated using <code>mibian</code> and <code>scipy</code>.</li><li><strong>TelegramAlert</strong><br> 📘 <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/data-api-1/telegram" target="_blank" rel="noreferrer">Docs</a><br> Send instant Telegram alerts for strategy events, order triggers, and status updates.</li></ol><p>🔗 Python equivalents available at:<br><a href="https://docs.algo.wesoftcorp.com/trading-platform/python" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/trading-platform/python</a></p><hr><h3 id="broker-api-fixes" tabindex="-1"><strong>Broker &amp; API Fixes</strong> <a class="header-anchor" href="#broker-api-fixes" aria-label="Permalink to &quot;**Broker &amp; API Fixes**&quot;">​</a></h3><h4 id="kotak-securities-critical-update" tabindex="-1"><strong>Kotak Securities (Critical Update)</strong> <a class="header-anchor" href="#kotak-securities-critical-update" aria-label="Permalink to &quot;**Kotak Securities (Critical Update)**&quot;">​</a></h4><ul><li>Migrated to <strong>Kotak API v2</strong> — contributed by <strong>@crypt0inf0</strong>.</li><li>Switched from <strong>SMS-based OTP</strong> to <strong>TOTP-based OTP</strong> authentication.</li><li>New API Key / Secret generation workflow introduced.<br> → Read the updated docs: <a href="https://docs.algo.wesoftcorp.com/connect-brokers/brokers/kotak-securities" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/connect-brokers/brokers/kotak-securities</a></li></ul><h4 id="dhan-api-update" tabindex="-1"><strong>Dhan API Update</strong> <a class="header-anchor" href="#dhan-api-update" aria-label="Permalink to &quot;**Dhan API Update**&quot;">​</a></h4><ul><li>Adopted <strong>new API Key–based authentication</strong> replacing old token-based flow.</li><li>Supports <strong>Static IP whitelisting</strong> for improved reliability.</li><li>Updated <code>.env</code> structure — refer to the new Dhan configuration guide:<br><a href="https://docs.algo.wesoftcorp.com/connect-brokers/brokers/dhan" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/connect-brokers/brokers/dhan</a></li></ul><h4 id="other-broker-fixes" tabindex="-1"><strong>Other Broker Fixes</strong> <a class="header-anchor" href="#other-broker-fixes" aria-label="Permalink to &quot;**Other Broker Fixes**&quot;">​</a></h4><ul><li><strong>Aliceblue</strong> — WebSocket authentication issue resolved.</li><li><strong>Fivepaisa</strong> — Websocket Implementation</li><li><strong>PayTM</strong> — Websocket Implementation</li><li><strong>Zerodha</strong> — Added data error handling for users with free personal APIs (no data/WebSocket access).</li></ul><hr><h3 id="deployment-server-enhancements" tabindex="-1"><strong>Deployment &amp; Server Enhancements</strong> <a class="header-anchor" href="#deployment-server-enhancements" aria-label="Permalink to &quot;**Deployment &amp; Server Enhancements**&quot;">​</a></h3><ol><li><strong>Universal Linux Support via install.sh</strong><ul><li>Tradeboard can now be installed across <strong>multiple distros with custom domains</strong>.</li><li>Script supports: <ul><li><strong>Debian-based:</strong> Ubuntu, Mint, Zorin, Pop!_OS, Raspbian</li><li><strong>RHEL-based:</strong> CentOS, Fedora, Rocky, AlmaLinux, Amazon Linux, Oracle Linux</li><li><strong>Arch-based:</strong> Arch, Manjaro, EndeavourOS, CachyOS</li></ul></li><li>Recommended: <strong>Custom Domain + Cloudflare Configuration</strong></li><li>Script: <a href="https://github.com/wesoftcorp/tradeboard-docs/blob/main/install/install.sh" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs/blob/main/install/install.sh</a></li></ul></li><li><strong>Docker Improvements</strong><ul><li>Updated base image to latest <strong>Python version</strong>.</li><li>Reduced vulnerabilities using <strong>Snyk-optimized Dockerfile</strong>.</li><li>Added persistent volumes for <code>/strategies</code> and <code>/keys</code>.</li><li>Enhanced Nginx configuration for custom domains and HTTP2.</li></ul></li><li><strong>Security Update</strong><ul><li>Disabled <strong>automatic IP bans</strong> to avoid self-lockouts.</li><li>Manual IP management now handled via the <code>/security</code> dashboard.</li></ul></li></ol><hr><h3 id="sandbox-margin-fixes" tabindex="-1"><strong>Sandbox &amp; Margin Fixes</strong> <a class="header-anchor" href="#sandbox-margin-fixes" aria-label="Permalink to &quot;**Sandbox &amp; Margin Fixes**&quot;">​</a></h3><ul><li>Fixed <strong>Sandbox Margin Issue</strong> (thanks to @Dipesh).</li><li>DB migration required for this release — follow upgrade guide:<br><a href="https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/installation-guidelines/getting-started/upgrade</a></li><li>Fresh installations do <strong>not</strong> require migration.</li></ul><hr><h3 id="dependencies" tabindex="-1"><strong>Dependencies</strong> <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;**Dependencies**&quot;">​</a></h3><p><strong>New Python Packages Added:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mibian</span></span>
<span class="line"><span>scipy</span></span></code></pre></div><p><strong>Configuration:</strong></p><ul><li>No changes to <code>.env</code> version (v1.0.4 remains compatible).</li></ul><hr><h3 id="summary" tabindex="-1"><strong>Summary</strong> <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;**Summary**&quot;">​</a></h3><p>Version <strong>1.0.0.36</strong> delivers a <strong>major performance boost</strong>, <strong>new Options APIs</strong>, and <strong>critical broker upgrades</strong>.<br> From <strong>faster startup times</strong> and <strong>real-time latency analytics</strong> to <strong>Kotak v2 migration</strong> and <strong>Telegram alerting.</strong></p>`,33)])])}const u=r(n,[["render",s]]);export{h as __pageData,u as default};
